def _verify_manifest(base_dir):
    """BUG-20: Verify every bundled file exists and matches its exact SHA-256 digest."""
    base_dir = Path(base_dir)
    for rel_path, expected_hash in _EMBEDDED_MANIFEST_SHA256.items():
        candidate = base_dir / rel_path
        if not candidate.exists():
            return False, f"Missing file: {rel_path}"
        try:
            actual_hash = hashlib.sha256(candidate.read_bytes()).hexdigest()
        except OSError as exc:
            return False, f"Unreadable file {rel_path}: {exc}"
        if actual_hash != expected_hash:
            return False, f"SHA-256 mismatch on {rel_path}"
    return True, "OK"


def _purge_stale_futures_modules(expected_root, force=False):
    """Purge cached `futures.*` modules from `sys.modules` after hot-reload or self-bootstrap upgrade on Streamlit Cloud."""
    import importlib
    importlib.invalidate_caches()
    is_test = bool(
        "pytest" in sys.modules
        or os.getenv("PYTEST_CURRENT_TEST")
        or str(os.getenv("COINAGENT_TEST_MODE", "")).lower() in ("1", "true", "yes", "on")
    )
    needs_purge = bool(force)
    mod_fut = sys.modules.get("futures")
    mod_db = sys.modules.get("futures.db_backend")
    mod_sc = sys.modules.get("futures.screener")
    if not needs_purge:
        if mod_db is not None and (not hasattr(mod_db, "DEFAULT_USER_PREFERENCES") or not hasattr(mod_db, "_upgrade_postgres_int4_columns")):
            needs_purge = True
        elif mod_sc is not None and not hasattr(mod_sc, "classify_m15_error"):
            needs_purge = True
        elif not is_test and mod_fut is not None and getattr(mod_fut, "_BUNDLE_SHA256", None) != _EMBEDDED_BUNDLE_SHA256:
            needs_purge = True
        elif mod_db is not None and getattr(mod_db, "__file__", None):
            try:
                loaded_root = Path(mod_db.__file__).resolve().parent.parent
                if loaded_root != Path(expected_root).resolve():
                    needs_purge = True
            except Exception:
                pass
    if needs_purge:
        for mod_name in [k for k in list(sys.modules) if k == "futures" or k.startswith("futures.")]:
            sys.modules.pop(mod_name, None)
        importlib.invalidate_caches()


def _bootstrap_project_files(target_dir=None):
    """BUG-20: Verify SHA-256 manifest of `futures/` and atomically restore/upgrade via staging directory."""
    app_root = Path(target_dir) if target_dir is not None else Path(__file__).resolve().parent
    if str(app_root) in sys.path:
        sys.path.remove(str(app_root))
    sys.path.insert(0, str(app_root))

    ok, _ = _verify_manifest(app_root)
    if ok:
        if target_dir is None:
            _purge_stale_futures_modules(app_root, force=False)
        return app_root

    dest_root = app_root
    try:
        (dest_root / "futures").mkdir(parents=True, exist_ok=True)
        probe = dest_root / "futures" / ".write_probe"
        probe.write_text("ok", encoding="utf-8")
        probe.unlink(missing_ok=True)
    except OSError:
        dest_root = Path(tempfile.gettempdir()) / "coinagentx_runtime_v602"
        dest_root.mkdir(parents=True, exist_ok=True)
        if str(dest_root) in sys.path:
            sys.path.remove(str(dest_root))
        sys.path.insert(0, str(dest_root))
        ok_fallback, _ = _verify_manifest(dest_root)
        if ok_fallback:
            if target_dir is None:
                _purge_stale_futures_modules(dest_root, force=True)
            return dest_root

    raw_zip = base64.b64decode(_EMBEDDED_BUNDLE_B64)
    if hashlib.sha256(raw_zip).hexdigest() != _EMBEDDED_BUNDLE_SHA256:
        raise RuntimeError("Embedded project bundle SHA-256 integrity check failed.")

    # Atomic staging extraction: extract and verify all hashes in a temporary staging directory first,
    # then atomically replace each target file via os.replace() so partial upgrades cannot occur.
    staging_parent = dest_root if os.access(dest_root, os.W_OK) else Path(tempfile.gettempdir())
    staging_dir = Path(tempfile.mkdtemp(prefix=".coinagent_stage_", dir=str(staging_parent)))
    try:
        with zipfile.ZipFile(io.BytesIO(raw_zip), "r") as zf:
            for member in zf.namelist():
                staged_file = staging_dir / member
                staged_file.parent.mkdir(parents=True, exist_ok=True)
                data = zf.read(member)
                expected = _EMBEDDED_MANIFEST_SHA256.get(member)
                if expected and hashlib.sha256(data).hexdigest() != expected:
                    raise RuntimeError(f"Staged file SHA-256 verification failed for {member}")
                staged_file.write_bytes(data)

        for member in _EMBEDDED_MANIFEST_SHA256:
            src_file = staging_dir / member
            dst_file = dest_root / member
            dst_file.parent.mkdir(parents=True, exist_ok=True)
            os.replace(str(src_file), str(dst_file))
    finally:
        shutil.rmtree(staging_dir, ignore_errors=True)

    if target_dir is None:
        _purge_stale_futures_modules(dest_root, force=True)
    return dest_root


_ACTIVE_ROOT = _bootstrap_project_files()

