        with st.expander("Keamanan & Otorisasi Server-Side"):
            st.caption(f"Peran sesi aktif: {session_info['role']} · Status Admin Secret: {'Terkonfigurasi' if engine.security.admin_configured else 'Belum diatur (Mode Read-Only)'}")
